              "name": "run_command",
              "args": "{\"command\":\"npm test \\u0026\\u0026 node -e \\\"\\nimport assert from 'node:assert/strict';\\nimport { OrderConsumer } from './src/workers/order_consumer.mjs';\\nimport { DedupStore } from './src/infra/dedup_store.mjs';\\nimport { DlqWriter } from './src/infra/dlq_writer.mjs';\\nimport { LockManager } from './src/infra/lock_manager.mjs';\\n\\nconst lockManager = new LockManager();\\nconst dedupStore = new DedupStore();\\nconst dlq = new DlqWriter();\\nconst consumer = new OrderConsumer({ lockManager, dedupStore, dlq, maxRetries: 3 });\\n\\n// 1. Normal commit\\nconst res1 = await consumer.consumeOrderEvent({ eventId: 'evt-1', orderId: 'ord-1', retryCount: 0 });\\nassert.deepEqual(res1, { processed: true, status: 'COMMITTED', orderId: 'ord-1' });\\nassert.equal(lockManager.held.size, 0);\\n\\n// 2. Duplicate ignored\\nconst res2 = await consumer.consumeOrderEvent({ eventId: 'evt-1', orderId: 'ord-1', retryCount: 0 });\\nassert.deepEqual(res2, { processed: false, status: 'DUPLICATE_IGNORED' });\\n\\n// 3. Dead letter on maxRetries\\nconst dlqEvt = { eventId: 'evt-2', orderId: 'ord-2', retryCount: 3 };\\nconst res3 = await consumer.consumeOrderEvent(dlqEvt);\\nassert.deepEqual(res3, { processed: false, status: 'DEAD_LETTER' });\\nassert.deepEqual(dlq.messages, [{ event: dlqEvt, reasonCode: 'MAX_RETRIES_EXCEEDED' }]);\\nassert.equal(lockManager.held.size, 0);\\n\\n// 4. Lock busy\\nawait lockManager.tryLease({ resourceKey: 'ord-3', ttlMs: 5000 });\\nconst res4 = await consumer.consumeOrderEvent({ eventId: 'evt-3', orderId: 'ord-3', retryCount: 0 });\\nassert.deepEqual(res4, { processed: false, status: 'LOCK_BUSY' });\\nawait lockManager.releaseLease({ resourceKey: 'ord-3' });\\n\\nconsole.log('Integration checks passed!');\\n\\\"\"}"
