        "r1": "import { DatabaseSync } from 'node:sqlite';\n\nexport class Migrator {\n  constructor(dbPath = ':memory:') {\n    this.db = new DatabaseSync(dbPath);\n    this.db.exec(`\n      CREATE TABLE IF NOT EXISTS _migrations (\n        version INTEGER PRIMARY KEY,\n        name TEXT NOT NULL,\n        down TEXT,\n        applied_at TEXT NOT NULL\n      )\n    `);\n  }\n\n  getApplied() {\n    const stmt = this.db.prepare('SELECT version, name, applied_at FROM _migrations ORDER BY version ASC');\n    return stmt.all();\n  }\n\n  currentVersion() {\n    const row = this.db.prepare('SELECT MAX(version) AS version FROM _migrations').get();\n    return row?.version ?? 0;\n  }\n\n  migrate(migrations = [], targetVersion = Infinity) {\n    // migrations: Array<{ version: number, name: string, up: string, down?: string }>\n    const sorted = [...migrations].sort((a, b) => a.version - b.version);\n    const appliedVersions = new Set(\n      this.db.prepare('SELECT version FROM _migrations').all().map((r) => r.version)\n    );\n    const insertStmt = this.db.prepare(\n      'INSERT INTO _migrations (version, name, down, applied_at) VALUES (?, ?, ?, ?)'\n    );\n\n    let applied = 0;\n    for (const m of sorted) {\n      if (m.version > targetVersion || appliedVersions.has(m.version)) {\n        continue;\n      }\n      this.db.exec('BEGIN');\n      try {\n        this.db.exec(m.up);\n        insertStmt.run(m.version, m.name, m.down ?? null, new Date().toISOString());\n        this.db.exec('COMMIT');\n        applied++;\n      } catch (err) {\n        this.db.exec('ROLLBACK');\n        throw err;\n      }\n    }\n    return { applied, version: this.currentVersion() };\n  }\n\n  rollback(migrations = [], steps = 1) {\n    const downMap = new Map(migrations.map((m) => [m.version, m.down]));\n    const rows = this.db\n      .prepare('SELECT version, name, down FROM _migrations ORDER BY version DESC LIMIT ?')\n      .all(steps);\n    const deleteStmt = this.db.prepare('DELETE FROM _migrations WHERE version = ?');\n\n    let rolledBack = 0;\n    for (const row of rows) {\n      const downSql = downMap.get(row.version) ?? row.down;\n      if (!downSql) {\n        throw new Error(`No down migration for version ${row.version} (${row.name})`);\n      }\n      this.db.exec('BEGIN');\n      try {\n        this.db.exec(downSql);\n        deleteStmt.run(row.version);\n        this.db.exec('COMMIT');\n        rolledBack++;\n      } catch (err) {\n        this.db.exec('ROLLBACK');\n        throw err;\n      }\n    }\n    return { rolledBack, version: this.currentVersion() };\n  }\n\n  close() {\n    this.db.close();\n  }\n}\n",
        "r2": "import { DatabaseSync } from 'node:sqlite';\n\nexport class Migrator {\n  constructor(dbPath = ':memory:') {\n    this.db = new DatabaseSync(dbPath);\n    this.db.exec(`\n      CREATE TABLE IF NOT EXISTS _migrations (\n        version INTEGER PRIMARY KEY,\n        name TEXT NOT NULL,\n        applied_at TEXT NOT NULL DEFAULT (datetime('now'))\n      )\n    `);\n  }\n\n  getApplied() {\n    return this.db\n      .prepare('SELECT version, name, applied_at FROM _migrations ORDER BY version ASC')\n      .all();\n  }\n\n  getVersion() {\n    const row = this.db\n      .prepare('SELECT MAX(version) AS version FROM _migrations')\n      .get();\n    return row?.version ?? 0;\n  }\n\n  migrate(migrations = []) {\n    // migrations: Array<{ version: number, name: string, up: string, down?: string }>\n    const sorted = [...migrations].sort((a, b) => a.version - b.version);\n    const appliedVersions = new Set(this.getApplied().map((m) => m.version));\n    const pending = sorted.filter((m) => !appliedVersions.has(m.version));\n\n    const insertStmt = this.db.prepare(\n      'INSERT INTO _migrations (version, name) VALUES (?, ?)'\n    );\n\n    let applied = 0;\n    for (const m of pending) {\n      this.db.exec('BEGIN');\n      try {\n        this.db.exec(m.up);\n        insertStmt.run(m.version, m.name);\n        this.db.exec('COMMIT');\n        applied++;\n      } catch (err) {\n        this.db.exec('ROLLBACK');\n        throw err;\n      }\n    }\n\n    return { applied, version: this.getVersion() };\n  }\n\n  rollback(migrations = [], steps = 1) {\n    const appliedList = this.getApplied().reverse().slice(0, steps);\n    const migrationMap = new Map(migrations.map((m) => [m.version, m]));\n    const deleteStmt = this.db.prepare('DELETE FROM _migrations WHERE version = ?');\n\n    let rolledBack = 0;\n    for (const record of appliedList) {\n      const m = migrationMap.get(record.version);\n      if (!m || !m.down) {\n        throw new Error(`Missing down migration for version ${record.version}`);\n      }\n      this.db.exec('BEGIN');\n      try {\n        this.db.exec(m.down);\n        deleteStmt.run(record.version);\n        this.db.exec('COMMIT');\n        rolledBack++;\n      } catch (err) {\n        this.db.exec('ROLLBACK');\n        throw err;\n      }\n    }\n\n    return { rolledBack, version: this.getVersion() };\n  }\n\n  close() {\n    this.db.close();\n  }\n}\n\n"
